return {
  json: {
    error: {
      code: "INVALID_INPUT",
      message: "product_id must be a non-empty string"
    }
  }
};

const rows = $input.all().map(item => item.json);

const productId = $('When Executed by Another Workflow')
  .first()
  .json.product_id.trim();

// Check whether the product exists
const productFound = rows.some(
  row => row.product_id === productId
);

if (!productFound) {
  return [{
    json: {
      product_id: productId,
      found: false,
      inventory_positions: [],
      incoming_inventory: []
    }
  }];
}

const inventoryPositions = [];
const incomingInventory = [];

const toDate = value =>
  value == null ? null : String(value).slice(0, 10);

const toTimestamp = value =>
  value == null ? null : new Date(value).toISOString();

for (const row of rows) {

  if (row.record_type === 'POSITION') {
    inventoryPositions.push({
      warehouse_id: row.warehouse_id,
      on_hand: row.on_hand,
      reserved: row.reserved,
      available: row.available,
      last_updated: toTimestamp(row.last_updated)
    });
  }

  if (row.record_type === 'INCOMING') {
    incomingInventory.push({
      incoming_id: row.incoming_id,
      warehouse_id: row.warehouse_id,
      quantity: row.incoming_quantity,
      expected_arrival: toDate(row.expected_arrival),
      status: row.incoming_status
    });
  }
}

return [{
  json: {
    product_id: productId,
    found: true,
    inventory_positions: inventoryPositions,
    incoming_inventory: incomingInventory
  }
}];
